// Separate maps for clean lookups without casts.
const RAID_NAMES: Record<number, string> = {
  1307: 'The Voidspire',
  1314: 'Dreamrift',
  1308: "March on Quel'Danas",
  1273: "Nerub'ar Palace",
  1296: 'Liberation of Undermine',
  1302: 'Manaforge Omega',
  1320: 'The Venomous Abyss',
  1317: 'The Tidebound Grotto',
};

const DUNGEON_NAMES: Record<number, string> = {
  1313: "Voidscar Arena",
  1309: "The Blinding Vale",
  1030: "Temple of Sethraliss",
  1202: "Ruby Life Pools",
  1304: "Murder Row",
  1041: "Kings' Rest",
  1311: "Den of Nalorakk",
  1322: "Altar of Fangs"
};

export function getSourceName(itemID: number): string | null {
  const src = ITEM_SOURCE[itemID];
  if (!src) return null;
  if (src.i === -87) return 'Mythic+';
  if (src.i === -1) return DUNGEON_NAMES[src.e] ?? null;
  return RAID_NAMES[src.i] ?? null;
}

// Returns a stable numeric grouping key for an item:
//   dungeons → dungeon encounter group ID (src.e)
//   raids    → raid instance ID (src.i)
//   seasonal M+ pool → -87
export function getSourceId(itemID: number): number | null {
  const src = ITEM_SOURCE[itemID];
  if (!src) return null;
  if (src.i === -87) return -87;
  if (src.i === -1) return src.e;
  return src.i;
}

export function getSourceNameById(sourceId: number): string | null {
  if (sourceId === -87) return 'Mythic+';
  return RAID_NAMES[sourceId] ?? DUNGEON_NAMES[sourceId] ?? null;
}

// Returns the boss name for an item using the static retailInstanceDB.
// Only works for raid items (instanceId > 0); dungeon pool items return null.
export function getBossName(itemID: number): string | null {
  const src = ITEM_SOURCE[itemID];
  if (!src || src.i <= 0) return null;
  const inst = retailInstanceDB[src.i];
  if (!inst) return null;
  return (inst as RaidInstanceEntry).bosses?.[src.e] ?? null;
}
